CREATE proc [dbo].[uspGetInvoicesForPaymentBySupplierId] @SpId as int as select i.InvoiceId,i.InvoiceNo,((select isnull(sum(Amount),0) from SupplierLedger where VN = i.InvoiceNo and [Type] = 'C')- (select isnull(sum(TotalAmount),0)  from PurchaseReturnMaster where InvoiceId = i.InvoiceId))  as TotalAmount,(select isnull(sum(Amount),0)  from SupplierLedger where InvoiceId = i.InvoiceId and [Type] = 'D' and VoucherType like '% PAYMENT VOUCHER') as TotalPaid,(((select isnull(sum(Amount),0) from SupplierLedger where VN =i.InvoiceNo and [Type] = 'C')- (select isnull(sum(TotalAmount),0) from PurchaseReturnMaster where InvoiceId = i.InvoiceId))-(select isnull(sum(Amount),0) from SupplierLedger where InvoiceId = i.InvoiceId and [Type] = 'D' and VoucherType like '% PAYMENT VOUCHER')) as Balance,'' as [Desc], Cast('0' as decimal(18,2)) as Amount,Cast('false' as bit) as [Select] from InvoiceMaster_CompanyNew i where i.VId = @SpId  and (((select isnull(sum(Amount),0) from SupplierLedger where VN = i.InvoiceNo and [Type] = 'C')- (select isnull(sum(TotalAmount),0) from PurchaseReturnMaster where InvoiceId = i.InvoiceId))-(select isnull(sum(Amount),0) from SupplierLedger where InvoiceId = i.InvoiceId and [Type] = 'D' and VoucherType like '% PAYMENT VOUCHER' )<> 0)